import sys
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    n = int(sys.stdin.readline())
    adj = [[] for _ in range(n+1)]
    for _ in range(n-1):
        a, b = map(int, sys.stdin.readline().split())
        adj[a].append(b)
        adj[b].append(a)

    # Precompute parent, depth, and subtree sizes for LCA
    parent = [0]*(n+1)
    depth = [0]*(n+1)
    size = [0]*(n+1)
    visited = [False]*(n+1)

    # BFS to set up parent and depth
    q = deque([1])
    visited[1] = True
    while q:
        u = q.popleft()
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                depth[v] = depth[u] + 1
                q.append(v)

    # Compute size of each subtree
    stack = [(1, False)]
    while stack:
        u, processed = stack.pop()
        if not processed:
            stack.append((u, True))
            for v in adj[u]:
                if v != parent[u]:
                    stack.append((v, False))
        else:
            size[u] = 1
            for v in adj[u]:
                if v != parent[u]:
                    size[u] += size[v]

    # Function to compute LCA
    def lca(u, v):
        while u != v:
            if depth[u] > depth[v]:
                u = parent[u]
            else:
                v = parent[v]
        return u

    # Function to compute distance between u and v
    def distance(u, v):
        ancestor = lca(u, v)
        return depth[u] + depth[v] - 2 * depth[ancestor]

    # Function to get the path from u to v
    def get_path(u, v):
        path_u = []
        path_v = []
        ancestor = lca(u, v)
        while u != ancestor:
            path_u.append(u)
            u = parent[u]
        while v != ancestor:
            path_v.append(v)
            v = parent[v]
        path_u.append(ancestor)
        path_v.reverse()
        return path_u + path_v

    t = int(sys.stdin.readline())
    for _ in range(t):
        u, v, x, y = map(int, sys.stdin.readline().split())
        if u == x and v == y:
            print(0)
            continue
        if u == x or u == y or v == x or v == y:
            # Check if they start at the same city
            if u == x or u == y or v == x or v == y:
                if u == x or u == y or v == x or v == y:
                    if u == x or v == x or u == y or v == y:
                        if u == x or u == y:
                            print(0)
                            continue
                        if v == x or v == y:
                            print(0)
                            continue
        # Compute the paths and their lengths
        path_uv = get_path(u, v)
        len_uv = len(path_uv) - 1
        path_xy = get_path(x, y)
        len_xy = len(path_xy) - 1

        # The runner's positions at time t
        def get_position(start, path_len, t):
            if t == 0:
                return start
            t = t % (2 * path_len)
            if t < path_len:
                return path_uv[t]
            else:
                return path_uv[2*path_len - t - 2]

        # Check if they meet at any time
        found = False
        max_time = 2 * 10**5
        for time in range(0, max_time + 1):
            pos_u = get_position(u, len_uv, time)
            pos_x = get_position(x, len_xy, time)
            if pos_u == pos_x:
                print(time)
                found = True
                break
        if not found:
            print(-1)

if __name__ == '__main__':
    main()
